import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";

import Headerreg from "../components/Header_reg";

export default function Registro() {
  const [nombre, setNombre] = useState("");
  const [correo, setCorreo] = useState("");
  const [password, setPassword] = useState("");

  const manejarRegistro = async (e) => {
    e.preventDefault();

    if (!nombre || !correo || !password) {
      alert("Por favor completa todos los campos");
      return;
    }

    try {
      // ⬇ Aquí debes colocar tu endpoint de Flask cuando lo tengas
      // const respuesta = await fetch("http://localhost:5000/registro", {
      //   method: "POST",
      //   headers: { "Content-Type": "application/json" },
      //   body: JSON.stringify({ nombre, correo, password }),
      // });

      // const data = await respuesta.json();

      // if (data.success) {
      //   alert("Registro exitoso");
      // } else {
      //   alert(data.message || "Error en el registro");
      // }

      // Temporal mientras conectamos backend:
      alert(`Usuario registrado:\nNombre: ${nombre}\nCorreo: ${correo}`);
    } catch (error) {
      alert("Error de conexión con el servidor");
      console.error(error);
    }
  };

    return (
        <>
            <Headerreg />
            <main>
                <form className="form-registro" onSubmit={manejarRegistro}>
                    <h2 className="subtitulo">Crear cuenta</h2>
                    {error && <p style={{color: 'red', textAlign: 'center'}}>{error}</p>}

                    {/* TIPO DE DOCUMENTO */}
                    <label htmlFor="t_doc">Tipo de Documento</label>
                    <select name="t_doc" id="t_doc" value={formData.t_doc} onChange={handleChange}>
                        <option value="CC">Cédula de Ciudadanía</option>
                        <option value="CE">Cédula de Extranjería</option>
                        <option value="TI">Tarjeta de Identidad</option>
                    </select>

                    {/* NÚMERO DE DOCUMENTO */}
                    <label htmlFor="id_usuario">Número de Documento</label>
                    <input
                        type="text"
                        id="id_usuario"
                        name="id_usuario"
                        value={formData.id_usuario}
                        onChange={handleChange}
                        placeholder="Número de identificación"
                    />

                    {/* NOMBRE Y APELLIDO */}
                    <label htmlFor="nom_1">Primer Nombre</label>
                    <input type="text" id="nom_1" name="nom_1" value={formData.nom_1} onChange={handleChange} placeholder="Primer nombre" />
                    
                    <label htmlFor="ape_1">Primer Apellido</label>
                    <input type="text" id="ape_1" name="ape_1" value={formData.ape_1} onChange={handleChange} placeholder="Primer apellido" />

                    {/* CORREO */}
                    <label htmlFor="correo">Correo electrónico</label>
                    <input type="email" id="correo" name="correo" value={formData.correo} onChange={handleChange} placeholder="Ingresa tu correo" />

                    {/* TELÉFONO */}
                    <label htmlFor="telefono">Teléfono</label>
                    <input type="tel" id="telefono" name="telefono" value={formData.telefono} onChange={handleChange} placeholder="Número de teléfono" />

                    {/* CONTRASEÑA */}
                    <label htmlFor="contrasena">Contraseña</label>
                    <input type="password" id="contrasena" name="contrasena" value={formData.contrasena} onChange={handleChange} placeholder="Ingresa tu contraseña" />

                    <button type="submit">Registrarse</button>

                    <div className="preguntas">
                        <p><Link to="/login">¿Ya tienes cuenta?</Link></p>
                    </div>
                </form>
            </main>
        </>
    );
}
